SunflowerHittingSet(H, k, T):
  let H' = {e in H : e ∩ T = ∅}
  if H' = ∅: return T
  if k = 0: return FAIL
  if ∃ sunflower S ⊆ H' with core c and |S| > k:
    for each v in c:
      result = SunflowerHittingSet(H, k-1, T ∪ {v})
      if result ≠ FAIL: return result
    return FAIL
  else:
    let e = arbitrary edge of H'
    for each v in e:
      result = SunflowerHittingSet(H, k-1, T ∪ {v})
      if result ≠ FAIL: return result
    return FAIL

Complexity: O(s^k · poly(|H|)) where s = core size
